function save(){if(state.mode==='title'||state.mode==='wardrobe')return;try{const value={custom:state.custom,visited:[...state.visited],area:state.area,position:{x:heroine.position.x,z:heroine.position.z},heading,transformed:state.transformed,finished:state.finished,savedAt:Date.now()};localStorage.setItem(STORAGE,JSON.stringify(value));saved=value;}catch{/* Private browsing can disable storage without interrupting play. */}}
function showToast(text,duration=3500){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,duration);}
function rebuildAvatars(){const oldPosition=heroine.position.clone();const oldRotation=heroine.rotation.y;scene.remove(heroine,partner);heroine=state.transformed?makeDog(false):makeHuman(state.custom);partner=state.transformed?makeDog(true):makeHuman({},true);heroine.position.copy(oldPosition);heroine.rotation.y=oldRotation;scene.add(heroine,partner);heroine.visible=state.mode!=='title';partner.visible=state.paired&&state.mode==='play';if(state.mode==='play')syncFormationFromHero();}
function groundHeight(x,z){const world=state.area==='inside'?interior:exterior;let height=-.1;for(const surface of world.surfaces){if(Math.abs(x-surface.x)<=surface.w/2+.0001&&Math.abs(z-surface.z)<=surface.d/2+.0001)height=Math.max(height,surface.height);}return height;}
function pairSpacing(){return state.transformed?2.45:2.0;}
function formationPoints(center,angle){const side=new THREE.Vector3(Math.cos(angle),0,-Math.sin(angle));return state.paired?[center.clone().addScaledVector(side,-pairSpacing()/2),center.clone().addScaledVector(side,pairSpacing()/2)]:[center.clone()];}
function applyFormation(){const points=formationPoints(formationCenter,heading);heroine.position.set(points[0].x,groundHeight(points[0].x,points[0].z),points[0].z);heroine.rotation.y=heading;if(state.paired){partner.position.set(points[1].x,groundHeight(points[1].x,points[1].z),points[1].z);partner.rotation.y=heading;}}
function fittingHeading(anchor){if(collisionAt(anchor.x,anchor.z))return undefined;if(!state.paired)return heading;for(const offset of [0,Math.PI/4,-Math.PI/4,Math.PI/2,-Math.PI/2,Math.PI*.75,-Math.PI*.75,Math.PI]){const angle=heading+offset,x=anchor.x+Math.cos(angle)*pairSpacing(),z=anchor.z-Math.sin(angle)*pairSpacing();if(!collisionAt(x,z)&&Math.abs(groundHeight(x,z)-groundHeight(anchor.x,anchor.z))<.25)return angle;}return undefined;}
function syncFormationFromHero(){const anchor=heroine.position.clone();let fit=fittingHeading(anchor);if(fit===undefined){const origin=anchor.clone();for(let radius=.35;radius<=5&&fit===undefined;radius+=.35)for(let i=0;i<16&&fit===undefined;i++){const angle=i*Math.PI/8;anchor.set(origin.x+Math.cos(angle)*radius,0,origin.z+Math.sin(angle)*radius);fit=fittingHeading(anchor);}if(fit===undefined){anchor.set(0,0,state.area==='inside'?29:41);fit=Math.PI;}}heading=fit;if(state.paired)formationCenter.copy(anchor).add(new THREE.Vector3(Math.cos(heading),0,-Math.sin(heading)).multiplyScalar(pairSpacing()/2));else formationCenter.copy(anchor);applyFormation();}
function updateHUD(){const n=state.visited.size;$('count').textContent=n;$('progress-ring').style.strokeDashoffset=100.531*(1-n/20);$('transform').hidden=n<10;$('transform-label').textContent=state.transformed?'变回我们':'一起变身';$('minimap').hidden=state.area!=='inside';$('chapter-note').textContent=state.area==='outside'?'沿着花园小径，去城堡看看吧。':n===20?'每一页，都是我们一起走过的日子。':state.paired?'这一次，我们牵着手慢慢走。':'靠近亮着爱心的地方，翻开一段回忆。';$('area-name').textContent=state.area==='outside'?'九又四分之三站台':'我们的回忆城堡';$('area-small').textContent=state.area==='outside'?'THE JOURNEY BEGINS':'A HOUSE FULL OF OUR DAYS';}
function closeAllDialogs(){document.querySelectorAll('#overlay > section').forEach(el=>el.hidden=true);$('overlay').hidden=true;state.dialog=null;currentMemory=null;keys.clear();if(modalLastFocus?.isConnected)modalLastFocus.focus({preventScroll:true});else canvas.focus({preventScroll:true});}
function showDialog(id){keys.clear();$('interact').hidden=true;if(!$('overlay').hidden){document.querySelectorAll('#overlay > section').forEach(el=>el.hidden=true);}else modalLastFocus=document.activeElement;$('overlay').hidden=false;$(id).hidden=false;state.dialog=id;const focusTarget=$(id).querySelector('button');if(focusTarget)focusTarget.focus({preventScroll:true});}
function restoreTitle(){state.mode='title';$('welcome').hidden=false;$('wardrobe').hidden=true;$('hud').hidden=true;exterior.root.visible=true;interior.root.visible=false;studio.visible=false;heroine.visible=false;partner.visible=false;heroShadow.visible=false;partnerShadow.visible=false;sun.position.set(-25,45,32);sun.target.position.set(0,0,-10);scene.fog.near=85;scene.fog.far=175;}
